from pathlib import Path
import subprocess
root = Path('build/field-defaults-regression/compilation')
root.mkdir(parents=True, exist_ok=True)
source = '''public record Foo() {
    record Component(String value) {}
    static class Holder { int value = 1; }
    enum Choice { ONLY; int value = 1; }
}
interface Interface {}
@interface Annotation {}
'''
java = Path('/usr/lib/jvm/java-17-openjdk-arm64/bin')
jar = str(Path('dist/lombok.jar').resolve())
for private, final in ((False, False), (True, False), (False, True), (True, True)):
    case = root / ('private-%s-final-%s' % (private, final))
    case.mkdir(exist_ok=True)
    (case / 'lombok.config').write_text('config.stopBubbling = true\nlombok.fieldDefaults.defaultPrivate = %s\nlombok.fieldDefaults.defaultFinal = %s\n' % (str(private).lower(), str(final).lower()))
    (case / 'Foo.java').write_text(source)
    subprocess.run([str(java / 'javac'), '-cp', jar, '-d', str(case), str(case / 'Foo.java')], check=True)
    for name in ('Foo$Holder', 'Foo$Choice'):
        output = subprocess.check_output([str(java / 'javap'), '-private', '-cp', str(case), name], text=True)
        expected = ('private ' if private else '') + ('final ' if final else '') + 'int value;'
        assert expected in output, (name, expected, output)
    output = subprocess.check_output([str(java / 'javap'), '-private', '-cp', str(case), 'Foo$Component'], text=True)
    assert 'private final java.lang.String value;' in output, output
    (case / 'Explicit.java').write_text('@lombok.experimental.FieldDefaults(makeFinal = true)\nrecord Explicit() {}\n')
    rejected = subprocess.run([str(java / 'javac'), '-cp', jar, '-d', str(case), str(case / 'Explicit.java')], capture_output=True, text=True)
    assert rejected.returncode != 0, 'Explicit @FieldDefaults must be rejected'
    assert '@FieldDefaults is only supported on a class or an enum.' in rejected.stderr, rejected.stderr
    print('Passed compilation and explicit-annotation checks: private=%s, final=%s' % (private, final))
